async function api<T>(url: string, options?: RequestInit): Promise<T> {
  const response = await fetch(url, options); const result: any = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(result.error ?? "操作失败，请稍后重试。"); return result as T;
}
function badgeClass(status: string) {
  if (status === "approved") return "bg-emerald-50 text-emerald-700 border-emerald-200";
  if (status === "submitted") return "bg-amber-50 text-amber-700 border-amber-200";
  if (status === "returned" || status === "missing") return "bg-red-50 text-red-700 border-red-200";
  return "bg-slate-100 text-slate-600 border-slate-200";
}

