  const department=departmentById(departmentId); const isDepartment=role==="department"; const viewOnly=isDepartment&&!isFillableDate(date); const shiftDate=(days:number)=>setDate(addDays(date,days)); return <div className="mb-5 flex flex-col gap-3 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm font-bold text-slate-900">工作日期</p><p className="mt-1 text-xs text-slate-500">{formatChineseDate(date)}{department?` · ${department.project}项目`:""}{viewOnly?<span className="ml-2 rounded bg-amber-100 px-1.5 py-0.5 font-bold text-amber-800">仅可查看</span>:null}</p></div><div className="flex flex-wrap items-center gap-2"><Button variant="outline" size="sm" onClick={()=>shiftDate(-1)}>前一天</Button>{isDepartment?<Button variant="outline" size="sm" disabled={date>=today()} onClick={()=>shiftDate(1)}>后一天</Button>:null}<Button variant="outline" size="sm" onClick={()=>setDate(today())}>今天</Button><Input type="date" value={date} max={isDepartment?today():undefined} onChange={(event)=>setDate(event.target.value)} className="w-[152px]"/>{!isDepartment?<Select value={project} onValueChange={setProject}><SelectTrigger className="w-[112px]"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="全部">全部项目</SelectItem><SelectItem value="启皓">启皓</SelectItem><SelectItem value="五栋">五栋</SelectItem></SelectContent></Select>:null}<Button variant="outline" size="icon" onClick={onReload} aria-label="刷新" disabled={loading}><RefreshCw className={loading?"animate-spin":""}/></Button></div></div>;
