function blankFollowup(): Followup { return { kind:"follow",category:"其他",content:"",quantity:"",unit:"",status:"in_progress",responsiblePerson:"",dueDate:"",completedDate:"",isAbnormal:false,notes:"" }; }
const EMPTY_FOLLOWUPS: Followup[] = [];
function reportDraft(report: DailyReport | undefined, department: DepartmentDefinition, date: string, carried: Followup[] = EMPTY_FOLLOWUPS): DailyReport {
  const metrics=Object.fromEntries(department.metrics.map((metric)=>[metric.key, report?.metrics?.[metric.key] ?? (metric.type==="status"?"done":0)]));
  const baseFollowups=(report?.followups??[]); const extra=carried.filter((item)=>!baseFollowups.some((existing)=>existing.id&&existing.id===item.id));
  return { id:report?.id,reportDate:date,departmentId:department.id,reporterName:report?.reporterName==="历史导入"?"":report?.reporterName??"",routineStatus:report?.routineStatus??"normal",status:report?.status??"draft",notes:report?.notes??"",reviewComment:report?.reviewComment??"",confirmedZero:report?.confirmedZero??false,metrics,followups:[...baseFollowups,...extra].map((item)=>({...item,content:item.content??"",quantity:item.quantity??"",unit:item.unit??"",responsiblePerson:item.responsiblePerson??"",notes:item.notes??"",dueDate:item.dueDate??"",completedDate:item.completedDate??""})),photos:report?.photos??[] };
}

const MAX_PHOTO_BYTES = Math.floor(1.5 * 1024 * 1024);
const MAX_PHOTOS = 6;
function photoThumbSrc(photo: ReportPhoto) { if (photo.thumbUrl) return photo.thumbUrl; return photo.url.includes("?") ? `${photo.url}&size=thumb` : `${photo.url}?size=thumb`; }
async function compressPhoto(file: File) {
  if (!/^image\/(jpeg|png|webp)$/.test(file.type)) return file;
  if ((file.type === "image/jpeg" || file.type === "image/webp") && file.size <= MAX_PHOTO_BYTES) return file;
  const url = URL.createObjectURL(file);
  try {
    const image = await new Promise<HTMLImageElement>((resolve, reject) => { const element = new Image(); element.onload = () => resolve(element); element.onerror = reject; element.src = url; });
    let scale = Math.min(1, 2048 / Math.max(image.width, image.height, 1));
    let quality = 0.82;
    let blob: Blob | null = null;
    for (let attempt = 0; attempt < 6; attempt++) {
      const canvas = document.createElement("canvas");
      canvas.width = Math.max(1, Math.round(image.width * scale));
      canvas.height = Math.max(1, Math.round(image.height * scale));
      canvas.getContext("2d")?.drawImage(image, 0, 0, canvas.width, canvas.height);
      blob = await new Promise((resolve) => canvas.toBlob(resolve, "image/jpeg", quality));
      if (blob && blob.size <= MAX_PHOTO_BYTES) break;
      quality = Math.max(0.5, quality - 0.08);
      scale *= 0.8;
    }
    if (!blob || (file.size <= MAX_PHOTO_BYTES && blob.size >= file.size)) return file;
    return new File([blob], file.name.replace(/\.[^.]+$/, ".jpg"), { type: "image/jpeg" });
  } catch { return file; }
  finally { URL.revokeObjectURL(url); }
}
function PhotoGallery({ photos, className, tileClassName, showCaption = false, onRemove, children }: { photos: ReportPhoto[]; className: string; tileClassName: string; showCaption?: boolean; onRemove?: (id: string) => void; children?: ReactNode }) {
  const [activeId, setActiveId] = useState<string | null>(null);
  const active = photos.find((photo) => photo.id === activeId) ?? null;
  return <div className={className}>
    {photos.map((photo) => <div key={photo.id} className={`group relative overflow-hidden bg-slate-100 ${tileClassName}`}>
      <button type="button" className="block w-full" onClick={() => setActiveId(photo.id)} aria-label={photo.caption || photo.fileName || "查看照片"}>
        <img src={photoThumbSrc(photo)} alt={photo.caption || photo.fileName} loading="lazy" className="aspect-[4/3] w-full object-cover" />
      </button>
      {showCaption && photo.caption ? <p className="bg-white px-2 py-1.5 text-xs text-slate-600">{photo.caption}</p> : null}
      {onRemove ? <Button size="icon-sm" variant="destructive" className="absolute right-2 top-2" onClick={() => onRemove(photo.id)}><X /></Button> : null}
    </div>)}
    {children}
    <Dialog open={active !== null} onOpenChange={(open) => { if (!open) setActiveId(null); }}>
      <DialogContent className="sm:max-w-3xl">
        <DialogHeader>
          <DialogTitle>{active?.caption || "现场照片"}</DialogTitle>
          <DialogDescription>原图。日报日期超过30天的照片只保留缩略图。</DialogDescription>
        </DialogHeader>
        {active ? <img src={active.url} alt={active.caption || active.fileName} className="max-h-[70vh] w-full rounded-lg bg-slate-100 object-contain" /> : null}
      </DialogContent>
    </Dialog>
  </div>;
}

function DepartmentForm({ department, date, report, reload, asAdmin=false, carried=EMPTY_FOLLOWUPS, onDirtyChange }: { department:DepartmentDefinition;date:string;report?:DailyReport;reload:()=>Promise<void>;asAdmin?:boolean;carried?:Followup[];onDirtyChange?:(dirty:boolean)=>void }) {
  const [draft,setDraft]=useState(()=>reportDraft(report,department,date,carried)); const [busy,setBusy]=useState(false); const [photoCaption,setPhotoCaption]=useState(""); const [saved,setSaved]=useState(()=>JSON.stringify(reportDraft(report,department,date,carried))); const fileRef=useRef<HTMLInputElement>(null);
  useEffect(()=>{const next=reportDraft(report,department,date,carried);setDraft(next);setSaved(JSON.stringify(next))},[report,department,date,carried]); const viewOnly=!asAdmin&&!isFillableDate(date); const locked=asAdmin?false:viewOnly||["submitted","approved"].includes(draft.status); const dirty=!locked&&JSON.stringify(draft)!==saved;
  useEffect(()=>{if(!dirty)return;const handler=(event:BeforeUnloadEvent)=>{event.preventDefault();event.returnValue=""};window.addEventListener("beforeunload",handler);return()=>window.removeEventListener("beforeunload",handler)},[dirty]);
  useEffect(()=>{onDirtyChange?.(dirty);return()=>onDirtyChange?.(false)},[dirty,onDirtyChange]);
  const updateMetric=(key:string,value:string|number)=>setDraft((current)=>({...current,metrics:{...current.metrics,[key]:value}}));
  const save=useCallback(async(submit=false)=>{if(viewOnly){toast.error(fillWindowText());return}setBusy(true);const metrics=Object.fromEntries(department.metrics.map((metric)=>[metric.key,metric.type==="status"?String(draft.metrics[metric.key]??"done"):Number(draft.metrics[metric.key]??0)||0]));try{if(asAdmin){await api("/api/action",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:"admin_save",reportId:draft.id,report:{...draft,metrics}})});toast.success("修改已保存；如该日期已发布，请重新发布正式日报")}else{await api("/api/action",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:submit?"submit_report":"save_report",report:{...draft,metrics}})});toast.success(submit?"日报已提交，等待管理员审核":"草稿已保存")}await reload()}catch(error){toast.error(error instanceof Error?error.message:"保存失败")}finally{setBusy(false)}},[draft,reload,department,asAdmin,viewOnly]);
  useEffect(()=>{ const context=(document as any).modelContext;if(!context?.registerTool)return;const controller=new AbortController();Promise.resolve(context.registerTool({name:"save_daily_report",title:"保存当前日报",description:"保存当前部门页面中的日报草稿。",inputSchema:{type:"object",properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async()=>{await save(false);return{status:"saved",date:draft.reportDate,department:department.name}}},{signal:controller.signal})).catch(()=>{});Promise.resolve(context.registerTool({name:"submit_daily_report",title:"提交当前日报",description:"确认并提交当前部门日报给管理员审核。",inputSchema:{type:"object",properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async()=>{await save(true);return{status:"submitted",date:draft.reportDate,department:department.name}}},{signal:controller.signal})).catch(()=>{});return()=>controller.abort()},[save,draft.reportDate,department.name]);
  const setAllNormal=()=>setDraft((current)=>({...current,routineStatus:"normal",metrics:{...current.metrics,...Object.fromEntries(department.metrics.filter((metric)=>metric.type==="status").map((metric)=>[metric.key,"done"]))}}));
  const addFollowup=()=>setDraft((current)=>({...current,followups:[...current.followups,blankFollowup()]}));
  const updateFollowup=(index:number,key:keyof Followup,value:any)=>setDraft((current)=>({...current,followups:current.followups.map((item,itemIndex)=>itemIndex===index?{...item,[key]:value}:item)}));
  const upload=async(file?:File)=>{if(!file||!draft.id||locked)return;if(draft.photos.length>=MAX_PHOTOS){toast.error("每个部门每天最多上传6张照片。");return}setBusy(true);try{const photo=await compressPhoto(file);const form=new FormData();form.set("reportId",draft.id);form.set("file",photo);form.set("caption",photoCaption.trim());await api("/api/upload",{method:"POST",body:form});toast.success("照片已上传");setPhotoCaption("");await reload()}catch(error){toast.error(error instanceof Error?error.message:"上传失败")}finally{setBusy(false);if(fileRef.current)fileRef.current.value=""}};
  const removePhoto=async(id:string)=>{try{await api("/api/action",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:"delete_photo",photoId:id})});await reload()}catch(error){toast.error(error instanceof Error?error.message:"删除失败")}};
  if(viewOnly&&!report)return <Card className="border-0 shadow-sm"><CardContent className="flex flex-col items-center gap-2 py-16 text-center"><Eye className="size-6 text-slate-400"/><p className="text-base font-bold text-slate-700">{formatChineseDate(date)}没有{department.name}的日报记录</p><p className="text-sm text-slate-500">{fillWindowText()}。</p></CardContent></Card>;
  return <div className="space-y-5"><Card className="gap-4 border-0 shadow-sm"><CardHeader className="gap-1"><div className="flex flex-wrap items-start justify-between gap-3"><div><CardTitle className="text-xl">{asAdmin?`管理员修改：${department.name}日报`:viewOnly?`${department.name}日报（查看）`:`${department.name}每日填报`}</CardTitle><CardDescription className="mt-2">按“固定工作、非固定工作、待跟进及重点工作”三部分填写。黄色区域需要确认或填写。</CardDescription></div><span className={`rounded-full border px-3 py-1 text-xs font-bold ${badgeClass(draft.status)}`}>{STATUS_LABEL[draft.status]??draft.status}</span></div>{draft.reviewComment?draft.status==="returned"?<div className="mt-3 rounded-xl bg-red-50 p-3 text-sm text-red-700">退回意见：{draft.reviewComment}</div>:<div className="mt-3 rounded-xl bg-slate-50 p-3 text-sm text-slate-600">审核备注：{draft.reviewComment}</div>:null}{viewOnly?<div className="mt-3 flex items-start gap-2 rounded-xl border border-amber-200 bg-amber-50 p-3 text-sm font-bold leading-6 text-amber-900"><Eye className="mt-1 size-4 shrink-0"/><p>{fillWindowText()}。如需修改更早的日报，请联系管理员。</p></div>:null}</CardHeader><CardContent className="space-y-6">
    <div className="grid gap-4 sm:grid-cols-2"><label className="space-y-2 text-sm font-bold">填报人<Input disabled={locked} value={draft.reporterName} onChange={(e)=>setDraft({...draft,reporterName:e.target.value})} placeholder="请输入姓名" className="bg-[#fff9df]"/></label><div className="space-y-2"><p className="text-sm font-bold">固定工作总体状态</p><Select disabled={locked} value={draft.routineStatus} onValueChange={(value)=>setDraft({...draft,routineStatus:value})}><SelectTrigger className="w-full bg-[#fff9df]"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="normal">全部正常</SelectItem><SelectItem value="abnormal">有异常</SelectItem><SelectItem value="not_done">未执行</SelectItem></SelectContent></Select></div></div>
    <section><SectionTitle title="一、固定工作" note="每天例行事项和量化数据；正常日点一次“全部正常”后核对数量即可。固定工作确认项计入“今日工作”统计"/><Button disabled={locked} onClick={setAllNormal} className="h-12 w-full rounded-xl bg-emerald-600 text-base hover:bg-emerald-700"><CheckCircle2/>今日固定工作全部正常</Button></section>
    {draft.routineStatus!=="normal"?<section><SectionTitle title="固定工作明细" note="请标出具体异常或未执行项目"/><div className="grid gap-3 sm:grid-cols-2">{department.metrics.filter((metric)=>metric.type==="status").map((metric)=><div key={metric.key} className="flex items-center justify-between rounded-xl border border-amber-200 bg-amber-50 p-3"><span className="text-sm font-bold">{metric.label}</span><Select disabled={locked} value={String(draft.metrics[metric.key]??"done")} onValueChange={(value)=>updateMetric(metric.key,value)}><SelectTrigger className="w-[110px] bg-white"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="done">已执行</SelectItem><SelectItem value="abnormal">异常</SelectItem><SelectItem value="not_done">未执行</SelectItem></SelectContent></Select></div>)}</div></section>:null}
    <section><SectionTitle title="固定工作量化数据" note="没有发生的项目保持0；量化数据用于服务数量统计，不计入“今日工作”项数"/><div className="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-3">{department.metrics.filter((metric)=>metric.type!=="status").map((metric)=><label key={metric.key} className="min-w-0 rounded-xl border border-amber-100 bg-[#fff9df] p-3"><span className="block truncate text-sm font-bold text-slate-700" title={metric.label}>{metric.label}</span><div className="mt-2 flex min-w-0 items-center gap-2"><Input disabled={locked} type="number" min="0" step={metric.type==="amount"?"0.01":"1"} value={draft.metrics[metric.key]==null||draft.metrics[metric.key]===""?"":String(draft.metrics[metric.key])} onChange={(event)=>updateMetric(metric.key,event.target.value===""?"":Number(event.target.value))} className="h-10 min-w-0 flex-1 bg-white text-lg font-bold tabular-nums"/><span className="shrink-0 text-xs text-slate-500">{metric.unit}</span></div></label>)}</div></section>
    <section><SectionTitle title="二、非固定工作（手动填写）" note="填写今日新增、临时或专项工作；固定工作不用重复填写"/><Textarea disabled={locked} value={draft.notes} onChange={(e)=>setDraft({...draft,notes:e.target.value})} placeholder="例：配合甲方临时会议布置、专项清洁、突发问题处理等。没有可不填。" className="min-h-28 bg-[#fff9df]"/></section>
    <section><div className="flex items-end justify-between gap-3"><SectionTitle title="三、待跟进及重点工作" note="填写需要后续推进、重点关注或异常风险的事项"/><Button disabled={locked} variant="outline" size="sm" onClick={addFollowup}><Plus/>新增事项</Button></div><div className="space-y-3">{draft.followups.length===0?<div className="rounded-xl border border-dashed p-5 text-center text-sm text-slate-400">今日暂无待跟进或重点工作</div>:draft.followups.map((item,index)=><FollowupEditor key={item.id??index} item={item} index={index} locked={locked} canRemove={asAdmin||!item.carried} update={updateFollowup} remove={()=>setDraft((current)=>({...current,followups:current.followups.filter((_,i)=>i!==index)}))}/>)}</div></section>
    <section><SectionTitle title="现场照片" note="可选上传，每个部门每天最多6张，先保存一次草稿后即可上传。"/>{!locked&&draft.photos.length<MAX_PHOTOS?<Input value={photoCaption} onChange={(event)=>setPhotoCaption(event.target.value)} placeholder="本次照片备注（可选），如：8层会议室消毒完成" className="mb-3 bg-amber-50"/>:null}<PhotoGallery photos={draft.photos} className="grid grid-cols-2 gap-3 sm:grid-cols-3" tileClassName="rounded-xl border" showCaption onRemove={locked?undefined:removePhoto}>{!locked&&draft.photos.length<MAX_PHOTOS?<button type="button" disabled={!draft.id||busy} onClick={()=>fileRef.current?.click()} className="flex aspect-[4/3] flex-col items-center justify-center gap-2 rounded-xl border border-dashed border-slate-300 bg-slate-50 text-sm font-bold text-slate-500 disabled:opacity-50"><Camera/><span>{draft.id?"上传照片":"请先保存草稿"}</span></button>:null}</PhotoGallery><input ref={fileRef} hidden type="file" accept="image/jpeg,image/png,image/webp,image/heic,image/heif" onChange={(event)=>upload(event.target.files?.[0])}/></section>
    {!locked?<div className="rounded-xl border border-amber-200 bg-amber-50 p-4"><label className="flex cursor-pointer items-start gap-3"><Checkbox checked={draft.confirmedZero} onCheckedChange={(checked)=>setDraft({...draft,confirmedZero:checked===true})}/><span className="text-sm font-bold leading-6 text-amber-900">我已核对所有数量，0代表今日没有发生，不是漏填。</span></label></div>:null}
    <div className="sticky bottom-3 z-20 flex gap-3 rounded-2xl border bg-white/95 p-3 shadow-lg backdrop-blur">{asAdmin?<Button disabled={busy} className="h-11 flex-1 bg-[#c40000] hover:bg-[#a90000]" onClick={()=>save(false)}><Save/>保存修改</Button>:locked?<div className="flex flex-1 items-center justify-center gap-2 text-center text-sm font-bold text-slate-500">{viewOnly?<><Eye className="shrink-0"/>{fillWindowText()}</>:<><Clock3/>日报已{draft.status==="approved"?"审核":"提交"}，等待管理员处理</>}</div>:<>{dirty?<span className="flex items-center gap-1.5 self-center pl-1 text-xs font-bold text-amber-600"><span className="size-2 rounded-full bg-amber-500"/>未保存</span>:null}<Button disabled={busy} variant="outline" className="h-11 flex-1" onClick={()=>save(false)}><Save/>保存草稿</Button><Button disabled={busy} className="h-11 flex-1 bg-[#c40000] hover:bg-[#a90000]" onClick={()=>save(true)}><Send/>确认提交</Button></>}</div>
  </CardContent></Card></div>;
}

function SectionTitle({title,note}:{title:string;note:string}){return <div className="mb-3"><h3 className="text-base font-black">{title}</h3><p className="mt-1 text-xs text-slate-500">{note}</p></div>}
function FollowupEditor({item,index,locked,update,remove,canRemove=true}:{item:Followup;index:number;locked:boolean;update:(i:number,k:keyof Followup,v:any)=>void;remove:()=>void;canRemove?:boolean}) { return <div className="rounded-2xl border border-red-100 bg-red-50/50 p-4"><div className="mb-3 flex items-start justify-between gap-3"><div><p className="text-sm font-black text-red-900">待跟进/重点工作 {index+1}</p><div className="mt-2 flex flex-wrap gap-1.5"><span className={`rounded px-2 py-0.5 text-[11px] font-bold ${item.kind==="key"?"bg-red-600 text-white":"bg-sky-100 text-sky-800"}`}>{item.kind==="key"?"重点 · 优先关注":"跟进 · 后续推进"}</span>{item.carried?<span className="rounded bg-slate-600 px-2 py-0.5 text-[11px] font-bold text-white">结转 · 上次未闭环带入</span>:null}{item.isAbnormal?<span className="rounded bg-red-100 px-2 py-0.5 text-[11px] font-bold text-red-700">异常 · 优先处理</span>:null}{item.status==="completed"?<span className="rounded bg-emerald-100 px-2 py-0.5 text-[11px] font-bold text-emerald-700">已完成</span>:null}</div></div>{!locked&&canRemove?<Button variant="ghost" size="icon-sm" onClick={remove}><X/></Button>:null}</div><div className="mb-4 rounded-xl border border-sky-100 bg-sky-50 p-3 text-xs leading-5 text-slate-600"><b className="text-sky-800">填写提示：</b>“跟进”是需要后续推进的事项；“结转”由前一天未闭环事项自动带入；勾选“异常”表示风险或需优先处理；处理完成后请选择“已完成”并填写完成日期。</div><div className="grid gap-3 sm:grid-cols-2"><div><FieldLabel>类型</FieldLabel><Select disabled={locked} value={item.kind??"follow"} onValueChange={(v)=>update(index,"kind",v)}><SelectTrigger className="w-full bg-white"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="follow">跟进事项（后续推进）</SelectItem><SelectItem value="key">重点工作（优先关注）</SelectItem></SelectContent></Select></div><div><FieldLabel>类别</FieldLabel><Select disabled={locked} value={item.category} onValueChange={(v)=>update(index,"category",v)}><SelectTrigger className="w-full bg-white"><SelectValue/></SelectTrigger><SelectContent>{FOLLOWUP_CATEGORIES.map((x)=><SelectItem key={x} value={x}>{x}</SelectItem>)}</SelectContent></Select></div><div><FieldLabel>状态</FieldLabel><Select disabled={locked} value={item.status} onValueChange={(v)=>update(index,"status",v)}><SelectTrigger className="w-full bg-white"><SelectValue/></SelectTrigger><SelectContent>{FOLLOWUP_STATUSES.map((x)=><SelectItem key={x.value} value={x.value}>{x.label}</SelectItem>)}</SelectContent></Select></div><label className="sm:col-span-2"><FieldLabel>事项内容</FieldLabel><Textarea disabled={locked} value={item.content} onChange={(e)=>update(index,"content",e.target.value)} className="bg-white"/></label><label className="flex items-center gap-2 rounded-lg border border-red-100 bg-white px-3 py-2 text-sm font-bold text-red-800"><Checkbox disabled={locked} checked={item.isAbnormal} onCheckedChange={(checked)=>update(index,"isAbnormal",checked===true)}/>标记为异常/风险事项</label><div className="hidden sm:block"/><label><FieldLabel>责任人</FieldLabel><Input disabled={locked} value={item.responsiblePerson} onChange={(e)=>update(index,"responsiblePerson",e.target.value)} className="bg-white"/></label><label><FieldLabel>{item.status==="completed"?"完成日期（必填）":"截止日期（必填）"}</FieldLabel><Input disabled={locked} type="date" value={item.status==="completed"?item.completedDate:item.dueDate} onChange={(e)=>update(index,item.status==="completed"?"completedDate":"dueDate",e.target.value)} className="bg-white"/></label><label><FieldLabel>数量</FieldLabel><Input disabled={locked} type="number" min="0" value={item.quantity} onChange={(e)=>update(index,"quantity",e.target.value===""?"":Number(e.target.value))} className="bg-white"/></label><label><FieldLabel>单位</FieldLabel><Input disabled={locked} value={item.unit} onChange={(e)=>update(index,"unit",e.target.value)} placeholder="项、次、件" className="bg-white"/></label><label className="sm:col-span-2"><FieldLabel>备注</FieldLabel><Input disabled={locked} value={item.notes} onChange={(e)=>update(index,"notes",e.target.value)} className="bg-white"/></label></div></div> }
function FieldLabel({children}:{children:ReactNode}){return <span className="mb-1.5 block text-xs font-bold text-slate-600">{children}</span>}

const GROUP_COLORS=["border-emerald-300 bg-emerald-100 text-emerald-900","border-sky-300 bg-sky-100 text-sky-900","border-amber-300 bg-amber-100 text-amber-900","border-violet-300 bg-violet-100 text-violet-900","border-teal-300 bg-teal-100 text-teal-900","border-rose-300 bg-rose-100 text-rose-900","border-indigo-300 bg-indigo-100 text-indigo-900","border-orange-300 bg-orange-100 text-orange-900","border-cyan-300 bg-cyan-100 text-cyan-900","border-lime-300 bg-lime-100 text-lime-900","border-fuchsia-300 bg-fuchsia-100 text-fuchsia-900","border-green-300 bg-green-100 text-green-900"];
const UNCOUNTED_TAG="border-slate-200 bg-slate-100 text-slate-500";

function ReportWorkBlocks({report,department,compact=false}:{report:DailyReport;department:DepartmentDefinition;compact?:boolean}){
  const routineLabel=report.routineStatus==="normal"?"固定工作均正常执行":report.routineStatus==="abnormal"?"固定工作存在异常":"固定工作有未执行项";
  const groupColors=new Map<string,string>();
  for(const metric of department.metrics)if(metric.workGroup&&!groupColors.has(metric.workGroup))groupColors.set(metric.workGroup,GROUP_COLORS[groupColors.size%GROUP_COLORS.length]);
  const statusTags=department.metrics.filter((metric)=>metric.type==="status");
  const numberTags=department.metrics.filter((metric)=>metric.type!=="status"&&Number(report.metrics?.[metric.key]??0)>0);
  const items=report.followups??[];
  const routine=countRoutineWork(department,report.metrics??{});
  const routineCount=routine.total;
  const notesCount=report.notes?.trim()?splitWorkLines(report.notes).length:0;
  const followTotal=(report.followups??[]).length;
  const followDone=(report.followups??[]).filter((item)=>item.status==="completed").length;
  const totalWork=routineCount+notesCount+followTotal;
  const doneWork=routine.done+notesCount+followDone;
  const openWork=followTotal-followDone;
  return <div className="space-y-3">
    <div className="rounded-xl border border-emerald-100 bg-emerald-50/60 p-3"><div className="flex flex-wrap items-center justify-between gap-2"><p className="text-xs font-black text-emerald-800">固定工作</p><span className="rounded-md bg-emerald-600 px-1.5 py-0.5 text-[10px] font-bold text-white">固定任务 {routineCount} 项 · 计入今日工作</span></div><p className="mt-1 text-sm font-bold text-slate-800">{routineLabel}</p><div className="mt-2 flex flex-wrap gap-1.5">{statusTags.map((metric)=>{const value=report.metrics?.[metric.key];const filled=value!=null;return <span key={metric.key} className={filled?`rounded-md border px-2 py-1 text-xs font-bold ${groupColors.get(metric.workGroup??"")??UNCOUNTED_TAG}`:`rounded-md border px-2 py-1 text-xs ${UNCOUNTED_TAG}`}><b>{metric.label}</b> · {value==="done"?"已执行":value==="abnormal"?"异常":value==="not_done"?"未执行":"未填"}</span>})}{numberTags.map((metric)=>{const counted=Boolean(metric.workGroup&&groupColors.has(metric.workGroup));return <span key={metric.key} className={counted?`rounded-md border px-2 py-1 text-xs font-bold ${groupColors.get(metric.workGroup!)}`:`rounded-md border px-2 py-1 text-xs ${UNCOUNTED_TAG}`}><b>{metric.label}</b> {String(report.metrics[metric.key])}{metric.unit}</span>})}</div><p className="mt-2 text-[10px] text-slate-400">深色=计入固定任务 · 同色=合并算1项 · 灰色=不计入</p></div>
    <div className="rounded-xl border border-slate-200 bg-slate-50 p-3"><div className="flex flex-wrap items-center justify-between gap-2"><p className="text-xs font-black text-slate-700">非固定工作</p>{notesCount?<span className="rounded-md bg-slate-200 px-1.5 py-0.5 text-[10px] font-bold text-slate-600">非固定 {notesCount} 条 · 计入今日工作</span>:null}</div>{report.notes?.trim()?<div className="mt-1 space-y-1.5">{splitWorkLines(report.notes).map((line,index)=><p key={index} className="flex items-start gap-2 border-b border-slate-100 pb-1.5 text-sm leading-6 text-slate-600 last:border-b-0 last:pb-0"><span className="mt-0.5 inline-flex size-5 shrink-0 items-center justify-center rounded-md bg-slate-200 text-[11px] font-bold text-slate-600">{index+1}</span><span>{line}</span></p>)}</div>:<p className="mt-1 text-sm leading-6 text-slate-600">今日无新增、临时或专项工作。</p>}</div>
    <div className="rounded-xl border border-red-100 bg-red-50/50 p-3"><div className="flex flex-wrap items-center justify-between gap-2"><p className="text-xs font-black text-red-800">待跟进及重点工作</p>{followTotal?<span className="rounded-md bg-red-600 px-1.5 py-0.5 text-[10px] font-bold text-white">待跟进 {followTotal} 条 · 计入今日工作</span>:null}</div>{items.length?<div className="mt-2 max-h-72 space-y-2 overflow-y-auto pr-2">{items.map((item,index)=><div key={item.id??index} className="rounded-lg bg-white p-2.5 text-sm leading-6"><p className="font-bold text-slate-800"><span className={`mr-2 inline-flex whitespace-nowrap rounded px-1.5 py-0.5 text-xs font-bold ${item.kind==="key"?"bg-red-600 text-white":"bg-sky-100 text-sky-800"}`}>{item.kind==="key"?"重点":"跟进"}</span>{item.carried?<span className="mr-2 inline-flex whitespace-nowrap rounded bg-slate-600 px-1.5 py-0.5 text-xs font-bold text-white">结转</span>:null}{item.isAbnormal?<span className="mr-2 inline-flex whitespace-nowrap rounded bg-red-100 px-1.5 py-0.5 text-xs font-bold text-red-700">异常</span>:null}{item.content||"未填写事项内容"}</p><p className="text-xs text-slate-500">{item.status==="completed"?"已完成":item.status==="paused"?"已暂停":item.status==="not_started"?"未开始":"跟进中"} · {item.responsiblePerson?`责任人：${item.responsiblePerson}`:"未填责任人"}{item.status==="completed"&&item.completedDate?` · 完成：${item.completedDate}`:item.dueDate?` · 截止：${item.dueDate}`:""}</p></div>)}</div>:<p className="mt-1 text-sm leading-6 text-slate-500">今日暂无待跟进或重点工作。</p>}</div>
    <div className="rounded-xl border border-slate-300 bg-white p-3 text-xs font-bold text-slate-700">小结：今日工作 {totalWork} 项（固定 {routineCount} · 非固定 {notesCount} · 跟进 {followTotal}） · 完成 {doneWork} 项 · 待跟进 {openWork} 项</div>
  </div>
}

function DashboardDepartmentCard({report}:{report:DailyReport}){const department=departmentById(report.departmentId)!;const visual=DEPARTMENT_VISUALS[department.id]??DEPARTMENT_VISUALS.qh_customer;const DepartmentIcon=visual.Icon;return <Card className={`gap-4 border shadow-sm ${visual.card}`}><CardHeader><div className="flex items-center justify-between gap-3"><div className="flex min-w-0 items-center gap-3"><div className={`flex size-11 shrink-0 items-center justify-center rounded-2xl text-white shadow-sm ${visual.icon}`}><DepartmentIcon className="size-5"/></div><div className="min-w-0"><CardTitle>{department.name}</CardTitle><CardDescription className="mt-1">{department.project}项目</CardDescription></div></div><span className={`shrink-0 whitespace-nowrap rounded-full border px-3 py-1 text-xs font-bold ${badgeClass(report.status)}`}>{STATUS_LABEL[report.status]??report.status}</span></div></CardHeader><CardContent className="space-y-4">{report.status==="missing"?<p className="rounded-xl bg-white/70 p-3 text-sm leading-6 text-slate-500">该部门尚未提交日报。</p>:<ReportWorkBlocks report={report} department={department}/>} {report.photos?.length?<PhotoGallery photos={report.photos.slice(0,6)} className="grid grid-cols-3 gap-2" tileClassName="rounded-lg"/>:null}</CardContent></Card>}

function calculateSnapshot(snapshot:Snapshot|undefined|null,project:string){const reports=(snapshot?.reports??[]).filter((report)=>project==="全部"||departmentById(report.departmentId)?.project===project);return{reports,kpis:buildKpis(reports.filter((report)=>report.status!=="missing"),snapshot?.reportDate??"")}}

function SnapshotDashboard({snapshot,monthly,project,mode}:{snapshot?:Snapshot|null;monthly:any[];project:string;mode:"admin"|"client"}){const exportRef=useRef<HTMLDivElement>(null);const view=calculateSnapshot(snapshot,project);const downloadPng=async()=>{if(!exportRef.current)return;try{toast.loading("正在生成长图…",{id:"png"});const {toPng}=await import("html-to-image");const value=await toPng(exportRef.current,{cacheBust:true,pixelRatio:2,backgroundColor:"#f4f6f8"});const link=document.createElement("a");link.download=`物业日报_${snapshot?.reportDate??today()}.png`;link.href=value;link.click();toast.success("长图已生成",{id:"png"})}catch{toast.error("长图生成失败，请稍后重试",{id:"png"})}};if(!snapshot)return <Card><CardContent className="py-16 text-center text-slate-500">该日期暂无已发布日报</CardContent></Card>;return <div className="space-y-5"><div className="flex flex-wrap justify-end gap-2 print:hidden"><Button variant="outline" onClick={downloadPng}><ImageDown/>导出长图</Button><Button variant="outline" onClick={()=>window.print()}><FileDown/>打印/PDF</Button><Button variant="outline" asChild><a href={`/api/export-ppt?date=${snapshot.reportDate}`}><Download/>导出PPT</a></Button><Button variant="outline" asChild><a href={`/api/export?month=${snapshot.reportDate.slice(0,7)}`}><Download/>月度Excel</a></Button></div><div ref={exportRef} className="space-y-5 rounded-3xl bg-[#f4f3ef] p-1 sm:p-3"><div className="relative overflow-hidden rounded-3xl border border-[#243043] bg-[#111827] p-6 text-white shadow-[0_18px_42px_rgba(15,23,42,.18)] sm:p-8"><div className="pointer-events-none absolute -right-24 -top-28 size-80 rounded-full bg-[#867259]/25 blur-3xl"/><div className="relative flex flex-col justify-between gap-6 sm:flex-row"><div><p className="inline-flex rounded-full border border-[#e6cab5]/30 bg-[#e6cab5]/10 px-3 py-1 text-xs font-bold tracking-wide text-[#f5d6c0]">新浪启皓 · 五栋物业服务</p><h2 className="mt-3 text-3xl font-black tracking-tight sm:text-4xl">{formatChineseDate(snapshot.reportDate)}工作日报</h2><p className="mt-3 text-sm text-slate-300">{project==="全部"?"全部项目":`${project}项目`} <span className="mx-2 text-[#d2a06c]">/</span> {mode==="client"?"正式发布版":"管理预览"}</p></div><div className="flex items-center gap-3 self-start rounded-2xl border border-white/10 bg-white/[.08] px-5 py-4 backdrop-blur-sm sm:self-auto"><div className="flex size-11 items-center justify-center rounded-xl bg-[#5f8d80]/20"><BadgeCheck className="size-7 text-[#70e0bd]"/></div><div><p className="text-xs font-medium text-slate-300">工作闭环率</p><p className="mt-0.5 text-3xl font-black tracking-tight">{view.kpis.completionRate==null?"--":view.kpis.completionRate}%</p></div></div></div></div>
    <div className="grid grid-cols-2 gap-3 lg:grid-cols-5">{[[ClipboardCheck,"今日工作",view.kpis.workItems,"项",false,`固定${view.kpis.routineCount??0} · 跟进${view.kpis.followupCount??0} · 非固定${view.kpis.notesCount??0}`],[CheckCircle2,"完成工作",view.kpis.completedItems,"项",false,null],[Wrench,"新增/完成报修",`${view.kpis.newRepairs}/${view.kpis.completedRepairs}`,"项",false,null],[Clock3,"未闭环",view.kpis.open,"项",view.kpis.open>0,null],[TriangleAlert,"异常/逾期",`${view.kpis.abnormal}/${view.kpis.overdue}`,"项",view.kpis.abnormal>0||view.kpis.overdue>0,null]].map(([Icon,label,value,unit,warn,sub])=>{const ItemIcon=Icon as typeof ClipboardCheck;const highlight=Boolean(warn);return <Card key={String(label)} className={`relative gap-2 overflow-hidden border py-4 shadow-[0_8px_20px_rgba(51,44,34,.07)] ${highlight?"border-[#e7c7bc] bg-[#fffaf7]":"border-[#e9e6df] bg-[#fffefd]"}`}><div className={`absolute inset-x-0 top-0 h-1 ${highlight?"bg-[#b85b45]":"bg-[#d8c9b7]"}`}/><CardContent className="px-4"><div className={`mb-4 flex size-10 items-center justify-center rounded-xl ${highlight?"bg-[#b85b45] text-white shadow-sm":"bg-[#f4f0e9] text-[#75614b]"}`}><ItemIcon className="size-5"/></div><p className="text-xs font-bold text-slate-500">{String(label)}</p><p className={`mt-1 text-2xl font-black tracking-tight ${highlight?"text-[#9d4334]":"text-slate-900"}`}>{String(value)}<span className="ml-1 text-xs font-medium text-slate-400">{String(unit)}</span></p>{sub?<p className="mt-1 text-[10px] font-medium text-slate-400">{String(sub)}</p>:null}</CardContent></Card>})}</div>
    <Card className="gap-4 border border-[#e9e6df] bg-[#fffefd] shadow-[0_8px_20px_rgba(51,44,34,.06)]"><CardHeader className="flex-row items-center justify-between"><div><CardTitle>主要服务数量</CardTitle><CardDescription className="mt-1">当天已完成的服务记录</CardDescription></div><span className="rounded-full bg-[#f2eee7] px-3 py-1 text-xs font-bold text-[#75614b]">服务汇总</span></CardHeader><CardContent className="grid grid-cols-3 gap-3 sm:grid-cols-7">{[["快递",view.kpis.service.express,"件"],["会议",view.kpis.service.meetings,"场"],["参会",view.kpis.service.participants,"人"],["水桶",view.kpis.service.water,"桶"],["巡检",view.kpis.service.patrol,"次"],["消毒",view.kpis.service.disinfect,"次"],["垃圾",view.kpis.service.garbage,"次"]].map(([label,value,unit],index)=><div key={String(label)} className={`rounded-2xl border p-3 text-center ${["border-[#d8e0dc] bg-[#f4f7f5]","border-[#e6d9c5] bg-[#faf6ee]","border-[#e0d9df] bg-[#f7f4f8]","border-[#dfe1c8] bg-[#f7f8ef]","border-[#d8e0dc] bg-[#f4f7f5]","border-[#e6d9c5] bg-[#faf6ee]","border-[#e0d9df] bg-[#f7f4f8]"][index]}`}><p className="text-xs font-medium text-slate-500">{label}</p><p className="mt-1 text-lg font-black tracking-tight text-slate-800">{value}<span className="ml-0.5 text-xs font-normal text-slate-400">{unit}</span></p></div>)}</CardContent></Card>
    <div className="space-y-4 lg:hidden">{view.reports.map((report)=><DashboardDepartmentCard key={report.departmentId} report={report}/>)}</div><div className="hidden items-start gap-4 lg:grid lg:grid-cols-2"><div className="space-y-4">{view.reports.filter((_,index)=>index%2===0).map((report)=><DashboardDepartmentCard key={report.departmentId} report={report}/>)}</div><div className="space-y-4">{view.reports.filter((_,index)=>index%2===1).map((report)=><DashboardDepartmentCard key={report.departmentId} report={report}/>)}</div></div>
    {monthly.length?<Card className="border-0 shadow-sm"><CardHeader><CardTitle>月度工作趋势</CardTitle><CardDescription>已发布日报的工作量、异常和未闭环变化</CardDescription></CardHeader><CardContent><ChartContainer config={{workItems:{label:"工作项",color:"#c40000"},open:{label:"未闭环",color:"#f59e0b"},abnormal:{label:"异常",color:"#64748b"}}} className="h-[260px] w-full"><LineChart data={monthly}><CartesianGrid vertical={false}/><XAxis dataKey="date" tickFormatter={(v)=>String(v).slice(5)}/><YAxis allowDecimals={false}/><ChartTooltip content={<ChartTooltipContent/>}/><Line type="monotone" dataKey="workItems" stroke="var(--color-workItems)" strokeWidth={3}/><Line type="monotone" dataKey="open" stroke="var(--color-open)" strokeWidth={2}/><Line type="monotone" dataKey="abnormal" stroke="var(--color-abnormal)" strokeWidth={2}/></LineChart></ChartContainer></CardContent></Card>:null}
  </div></div>}

function AdminDashboard({data,date,project,reload}:{data:AppData;date:string;project:string;reload:()=>Promise<void>}){const [review,setReview]=useState<{report:DailyReport;action:"return"|"reopen"}|null>(null);const [editing,setEditing]=useState<{department:DepartmentDefinition;report:DailyReport}|null>(null);const [comment,setComment]=useState("");const [publishing,setPublishing]=useState(false);const [publishCheck,setPublishCheck]=useState(false);const [rotate,setRotate]=useState<{id:string;label:string}|null>(null);const [newCode,setNewCode]=useState("");const reportsByDept=new Map((data.reports??[]).map((report)=>[report.departmentId,report]));const visible=DEPARTMENTS.filter((dept)=>project==="全部"||dept.project===project);const submittedCount=visible.filter((dept)=>{const r=reportsByDept.get(dept.id);return r&&["submitted","approved"].includes(r.status)}).length;const notReady=visible.filter((dept)=>{const r=reportsByDept.get(dept.id);return !r||!["submitted","approved"].includes(r.status)}).map((dept)=>dept.name);const action=async(body:any,success:string)=>{try{await api("/api/action",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body)});toast.success(success);await reload()}catch(error){toast.error(error instanceof Error?error.message:"操作失败")}};const publish=async()=>{setPublishing(true);await action({action:"publish",reportDate:date},"正式日报已发布");setPublishing(false)};const requestPublish=()=>{if(notReady.length)setPublishCheck(true);else publish()};return <><TabsContent value="review" className="space-y-4"><div className="flex flex-col justify-between gap-3 rounded-2xl bg-slate-950 p-5 text-white sm:flex-row sm:items-center"><div><p className="text-sm text-slate-300">{formatChineseDate(date)} · 已提交 {submittedCount}/{visible.length}</p><h2 className="mt-1 text-xl font-black">部门提交与审核</h2><div className="mt-3 h-1.5 w-48 overflow-hidden rounded-full bg-white/15"><div className="h-full rounded-full bg-emerald-400" style={{width:`${visible.length?Math.round(submittedCount/visible.length*100):0}%`}}/></div></div><Button disabled={publishing} onClick={requestPublish} className="bg-[#c40000] hover:bg-[#a90000]"><Send/>发布正式日报</Button></div><div className="grid gap-4 lg:grid-cols-2">{visible.map((department)=>{const report=reportsByDept.get(department.id);return <Card key={department.id} className="gap-4 border-0 shadow-sm"><CardHeader><div className="flex items-center justify-between"><div><CardTitle>{department.name}</CardTitle><CardDescription className="mt-1">{report?.reporterName?`填报人：${report.reporterName}`:"尚未填报"}</CardDescription></div><span className={`rounded-full border px-3 py-1 text-xs font-bold ${badgeClass(report?.status??"missing")}`}>{STATUS_LABEL[report?.status??"missing"]}</span></div></CardHeader><CardContent className="space-y-3">{report?<ReportWorkBlocks report={report} department={department}/>:<p className="rounded-xl bg-slate-50 p-3 text-sm leading-6">该部门尚未提交日报。发布后甲方页面会明确显示未提交。</p>}{report?.photos?.length?<PhotoGallery photos={report.photos.slice(0,6)} className="grid grid-cols-3 gap-2" tileClassName="rounded-lg"/>:null}<div className="flex flex-wrap gap-2">{report?.status==="submitted"?<><Button size="sm" onClick={()=>action({action:"approve",reportId:report.id},`${department.name}已审核`)}><Check/>通过</Button><Button size="sm" variant="outline" onClick={()=>{setReview({report,action:"return"});setComment("")}}><RotateCcw/>退回</Button></>:null}{report?.status==="approved"?<Button size="sm" variant="outline" onClick={()=>{setReview({report,action:"reopen"});setComment("")}}><RotateCcw/>重新打开</Button>:null}{report&&["draft","returned"].includes(report.status)?<Button size="sm" onClick={()=>action({action:"approve",reportId:report.id},`${department.name}已审核`)}><Check/>管理员直接通过</Button>:null}{report?<Button size="sm" variant="outline" onClick={()=>setEditing({department,report})}><Pencil/>修改内容</Button>:null}</div></CardContent></Card>})}</div></TabsContent><TabsContent value="dashboard"><SnapshotDashboard snapshot={data.snapshot} monthly={data.monthly??[]} project={project} mode="admin"/></TabsContent><TabsContent value="codes"><Card className="border-0 shadow-sm"><CardHeader><CardTitle>访问码管理</CardTitle><CardDescription>部门人员变动或访问码外泄时，可以在这里立即更换。更换后旧登录会失效。</CardDescription></CardHeader><CardContent className="divide-y">{(data.accessCodes??[]).map((item)=><div key={item.id} className="flex items-center justify-between gap-3 py-4"><div><p className="font-bold">{item.label}</p><p className="mt-1 text-xs text-slate-500">{item.role==="admin"?"管理权限":item.role==="client"?"只读权限":"部门填报权限"}</p></div><Button variant="outline" size="sm" onClick={()=>{setRotate({id:item.id,label:item.label});setNewCode("")}}>更换访问码</Button></div>)}</CardContent></Card></TabsContent><Dialog open={!!editing} onOpenChange={(open)=>!open&&setEditing(null)}><DialogContent className="max-h-[85vh] max-w-3xl overflow-y-auto">{editing?<DepartmentForm asAdmin department={editing.department} date={date} report={editing.report} reload={async()=>{setEditing(null);await reload()}}/>:null}</DialogContent></Dialog><Dialog open={publishCheck} onOpenChange={setPublishCheck}><DialogContent><DialogHeader><DialogTitle>仍有部门未提交</DialogTitle><DialogDescription>{notReady.join("、")} 共 {notReady.length} 个部门尚未提交日报。发布后甲方页面会显示这些部门为“未提交”，确认要现在发布吗？</DialogDescription></DialogHeader><DialogFooter><Button variant="outline" onClick={()=>setPublishCheck(false)}>再等等</Button><Button disabled={publishing} className="bg-[#c40000] hover:bg-[#a90000]" onClick={async()=>{setPublishCheck(false);await publish()}}>仍然发布</Button></DialogFooter></DialogContent></Dialog><Dialog open={!!review} onOpenChange={(open)=>!open&&setReview(null)}><DialogContent><DialogHeader><DialogTitle>{review?.action==="return"?"退回日报":"重新打开日报"}</DialogTitle><DialogDescription>填写清楚的修改意见，部门再次进入时会看到。</DialogDescription></DialogHeader><Textarea value={comment} onChange={(e)=>setComment(e.target.value)} placeholder="请输入修改意见"/><DialogFooter><Button variant="outline" onClick={()=>setReview(null)}>取消</Button><Button onClick={async()=>{if(review){await action({action:review.action,reportId:review.report.id,comment},"日报已退回");setReview(null)}}}>确认</Button></DialogFooter></DialogContent></Dialog><Dialog open={!!rotate} onOpenChange={(open)=>!open&&setRotate(null)}><DialogContent><DialogHeader><DialogTitle>更换{rotate?.label}访问码</DialogTitle><DialogDescription>设置新的6位数字访问码。请单独发送给对应人员。</DialogDescription></DialogHeader><Input inputMode="numeric" maxLength={6} value={newCode} onChange={(e)=>setNewCode(e.target.value.replace(/\D/g,"").slice(0,6))} placeholder="输入6位数字"/><DialogFooter><Button variant="outline" onClick={()=>setRotate(null)}>取消</Button><Button disabled={newCode.length!==6} onClick={async()=>{if(rotate){await action({action:"rotate_code",accessId:rotate.id,code:newCode},"访问码已更换");setRotate(null)}}}>确认更换</Button></DialogFooter></DialogContent></Dialog></>}

const ADMIN_TABS=[["review","今日审核"],["dashboard","日报看板"],["weekly","周报"],["monthly","月报"],["stats","数据统计"],["codes","访问码管理"]] as const;
const CLIENT_TABS=[["daily","日报看板"],["weekly","周报"],["monthly","月报"],["stats","数据统计"]] as const;
const DAILY_TABS:string[]=["review","dashboard","daily"];

export function PropertyDailyApp(){const [session,setSession]=useState<Session|null>(null);const [checked,setChecked]=useState(false);const [data,setData]=useState<AppData|null>(null);const [date,setDate]=useState(today());const [project,setProject]=useState("全部");const [loading,setLoading]=useState(false);const [tab,setTab]=useState("");const [periodFilters,setPeriodFilters]=useState<PeriodFilters>(DEFAULT_PERIOD_FILTERS);const updatePeriodFilters=useCallback((update:Partial<PeriodFilters>)=>setPeriodFilters((current)=>({...current,...update})),[]);const expireSession=useCallback(()=>{setSession(null);setData(null)},[]);const [formDirty,setFormDirty]=useState(false);const [pendingDate,setPendingDate]=useState<string|null>(null);const loadSeq=useRef(0);const load=useCallback(async(currentSession=session,currentDate=date,currentProject=project)=>{if(!currentSession)return;const request=++loadSeq.current;setLoading(true);try{const value=await api<AppData>(`/api/data?date=${currentDate}&project=${encodeURIComponent(currentProject)}`);if(request!==loadSeq.current)return;setData(value);if(currentSession.role==="client"&&value.selectedDate&&value.selectedDate!==currentDate)setDate(value.selectedDate)}catch(error){if(request!==loadSeq.current)return;if(error instanceof Error&&error.message.includes("登录")){setSession(null);setData(null)}toast.error(error instanceof Error?error.message:"加载失败")}finally{if(request===loadSeq.current)setLoading(false)}},[session,date,project]);useEffect(()=>{api<{session:Session}>("/api/session").then(({session})=>{setSession(session);setChecked(true);load(session,date,project)}).catch(()=>setChecked(true))},[]);useEffect(()=>{if(session)load(session,date,project)},[date,project]);const loginUser=async(code:string)=>{const result=await api<{session:Session}>("/api/session",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({code})});setSession(result.session);await load(result.session,date,project)};const logoutUser=async()=>{await fetch("/api/session",{method:"DELETE"});setSession(null);setData(null);setTab("");setPeriodFilters(DEFAULT_PERIOD_FILTERS)};if(!checked)return <div className="flex min-h-screen items-center justify-center bg-[#f4f6f8]"><RefreshCw className="size-7 animate-spin text-[#c40000]"/></div>;if(!session)return <LoginView onLogin={loginUser}/>;const department=departmentById(session.departmentId);const spinner=<div className="flex h-56 items-center justify-center"><RefreshCw className="animate-spin text-[#c40000]"/></div>;const changeDate=(value:string)=>{if(!isDateKey(value)||value<EARLIEST_DATE||value===date)return;if(formDirty){setPendingDate(value);return}setDate(value)};const dateBar=<DateProjectBar date={date} setDate={changeDate} project={project} setProject={setProject} role={session.role} departmentId={session.departmentId} onReload={()=>load()} loading={loading}/>;
  if(session.role==="department")return <div className="min-h-screen bg-[#f4f6f8]"><AppHeader session={session} onLogout={logoutUser}/><main className="mx-auto max-w-7xl px-4 py-5 sm:px-6 sm:py-7">{dateBar}{!department?null:data?.reportDate===date?<DepartmentForm department={department} date={date} report={data.reports?.[0]} carried={data.carried??EMPTY_FOLLOWUPS} reload={async()=>load()} onDirtyChange={setFormDirty}/>:spinner}<Dialog open={pendingDate!==null} onOpenChange={(open)=>{if(!open)setPendingDate(null)}}><DialogContent><DialogHeader><DialogTitle>有未保存的修改</DialogTitle><DialogDescription>当前日报还有未保存的修改，切换到{pendingDate?formatChineseDate(pendingDate):""}后这些修改会丢失。</DialogDescription></DialogHeader><DialogFooter><Button variant="outline" onClick={()=>setPendingDate(null)}>继续填写</Button><Button className="bg-[#c40000] hover:bg-[#a90000]" onClick={()=>{if(pendingDate)setDate(pendingDate);setPendingDate(null)}}>放弃修改并切换</Button></DialogFooter></DialogContent></Dialog></main></div>;
  const role=session.role;const tabs=role==="admin"?ADMIN_TABS:CLIENT_TABS;const activeTab=tabs.some(([value])=>value===tab)?tab:tabs[0][0];const showDay=(value:string,target:string)=>{setDate(value);setTab(target);window.scrollTo({top:0})};
  const periodView={role,anchorDate:date,project,setProject,filters:periodFilters,setFilters:updatePeriodFilters,onOpenDay:(value:string)=>showDay(value,role==="admin"?"dashboard":"daily"),onReviewDay:role==="admin"?(value:string)=>showDay(value,"review"):undefined,onAuthError:expireSession};
  return <div className="min-h-screen bg-[#f4f6f8]"><AppHeader session={session} onLogout={logoutUser}/><main className="mx-auto max-w-7xl px-4 py-5 sm:px-6 sm:py-7"><Tabs value={activeTab} onValueChange={setTab} className="gap-0"><TabsList className="mb-5 h-11 w-full justify-start overflow-x-auto rounded-xl bg-white p-1 shadow-sm print:hidden">{tabs.map(([value,label])=><TabsTrigger key={value} value={value} className="px-4">{label}</TabsTrigger>)}</TabsList>{DAILY_TABS.includes(activeTab)?dateBar:null}{role==="admin"?data?<AdminDashboard data={data} date={date} project={project} reload={async()=>load()}/>:loading&&DAILY_TABS.includes(activeTab)?spinner:null:<TabsContent value="daily">{loading&&!data?spinner:<SnapshotDashboard snapshot={data?.snapshot} monthly={data?.monthly??[]} project={project} mode="client"/>}</TabsContent>}<TabsContent value="weekly"><WeeklyReport {...periodView}/></TabsContent><TabsContent value="monthly"><MonthlyReport {...periodView}/></TabsContent><TabsContent value="stats"><StatsReport {...periodView}/></TabsContent></Tabs></main></div>}
